function prepareTronQuery(wallet, limit, timestamp) {
  if (typeof wallet !== "string" || !/^T[1-9A-HJ-NP-Za-km-z]{33}$/.test(wallet)) {
    throw new Error("Set a TRON Mainnet Base58 wallet address");
  }
  if (!Number.isInteger(limit) || limit < 1 || limit > 50)
    throw new Error("Set the page size between 1 and 50");
  const observed = Date.parse(timestamp);
  const cutoff = observed - 15 * 60 * 1000;
  if (!Number.isSafeInteger(cutoff) || cutoff < 0)
    throw new Error("The schedule did not provide a valid timestamp");

  const contract = "TR7NHqjeKQxGTCi8q8ZY4pL8otSzgjLj6t";
  const url =
    "https://apilist.tronscanapi.com/api/token_trc20/transfers?start=0&limit=" +
    limit +
    "&contract_address=" +
    contract +
    "&toAddress=" +
    wallet +
    "&end_timestamp=" +
    cutoff;
  return { url, wallet, limit, cutoff, contract };
}
const wallet = "YOUR_TRON_WALLET_ADDRESS";
const limit = 20;
return [{ json: prepareTronQuery(wallet, limit, $input.first().json.timestamp) }];

function summarizeTronTransfers(page, scope) {
  const rows = page?.token_transfers;
  const total = page?.rangeTotal;
  if (
    !Array.isArray(rows) ||
    rows.length > scope.limit ||
    !Number.isSafeInteger(total) ||
    total < rows.length
  ) {
    throw new Error("TronScan did not return a valid transfer page");
  }

  const results = [];
  for (const row of rows) {
    if (!row || typeof row !== "object") throw new Error("TronScan returned a malformed transfer");
    if (
      row.contract_address !== scope.contract ||
      row.to_address !== scope.wallet ||
      row.event_type !== "Transfer"
    )
      continue;
    if (!Number.isSafeInteger(row.block_ts) || row.block_ts < 0)
      throw new Error("TronScan returned an invalid block timestamp");
    if (row.block_ts > scope.cutoff) continue;
    if (
      row.tokenInfo?.tokenDecimal !== 6 ||
      typeof row.quant !== "string" ||
      !/^[0-9]{1,78}$/.test(row.quant) ||
      !/^[a-f0-9]{64}$/i.test(row.transaction_id ?? "") ||
      !/^T[1-9A-HJ-NP-Za-km-z]{33}$/.test(row.from_address ?? "") ||
      typeof row.confirmed !== "boolean" ||
      !["SUCCESS", "FAIL"].includes(row.finalResult)
    ) {
      throw new Error("TronScan returned invalid data for a matching USDT transfer");
    }

    const digits = row.quant.replace(/^0+(?=\d)/, "").padStart(7, "0");
    const amount = digits.slice(0, -6) + "." + digits.slice(-6);
    results.push({
      Coin: "Tether USD (USDT)",
      Network: "TRON (TRC20)",
      "From Address": row.from_address === scope.wallet ? "Your wallet" : row.from_address,
      "To Address": "Your wallet",
      "Amount (USDT)": amount,
      "Record Type": "Transfer",
      "Record Status": row.confirmed ? "Confirmed" : "Unconfirmed",
      "Transaction Result": row.revert === true ? "REVERTED" : row.finalResult,
      "Block Time": new Date(row.block_ts).toISOString(),
      "Record URL": "https://tronscan.org/#/transaction/" + row.transaction_id,
    });
  }

  return {
    Transactions: results.sort((a, b) => b["Block Time"].localeCompare(a["Block Time"])),
    moreAvailable: total > rows.length,
  };
}
return [
  { json: summarizeTronTransfers($input.first().json, $("Set wallet and page size").first().json) },
];
